export function parseCsv(csvText: string, datasetName: string = 'Uploaded Dataset'): Dataset {
  const lines = csvText.trim().split(/\r?\n/).filter((l) => l.trim().length > 0);
  if (lines.length < 2) {
    throw new Error('CSV must contain at least a header row and one data row.');
  }

  // Detect delimiter (, or \t or ;)
  const firstLine = lines[0];
  let delimiter = ',';
  if (firstLine.includes('\t')) delimiter = '\t';
  else if (firstLine.includes(';') && !firstLine.includes(',')) delimiter = ';';

  const rawHeaders = lines[0].split(delimiter).map((h) => h.trim().replace(/^["']|["']$/g, ''));
  const headers = rawHeaders.map((h, i) => h || `Var_${i + 1}`);

  const rows: Record<string, any>[] = [];
  for (let i = 1; i < lines.length; i++) {
    const rawTokens = lines[i].split(delimiter).map((t) => t.trim().replace(/^["']|["']$/g, ''));
    const rowObj: Record<string, any> = {};
    headers.forEach((h, hIdx) => {
      const val = rawTokens[hIdx];
      if (val === undefined || val === '') {
        rowObj[h] = null;
      } else {
        const num = Number(val);
        rowObj[h] = !isNaN(num) && val.trim() !== '' ? num : val;
      }
    });
    rows.push(rowObj);
  }

  // Deduce column types
  const columns = headers.map((colName) => {
    const values = rows.map((r) => r[colName]).filter((v) => v !== null && v !== undefined);
    const numericCount = values.filter((v) => typeof v === 'number').length;
    const isMostlyNumeric = values.length > 0 && numericCount / values.length >= 0.8;
    const distinctSet = new Set(values);

    let type: 'continuous' | 'categorical' | 'id' = 'continuous';
    if (colName.toLowerCase().includes('id') || distinctSet.size === rows.length) {
      type = 'id';
    } else if (!isMostlyNumeric || distinctSet.size <= 8) {
      type = 'categorical';
    } else {
      type = 'continuous';
    }

    return {
      name: colName,
      type,
      distinctCount: distinctSet.size,
      missingCount: rows.length - values.length,
      sampleValues: Array.from(distinctSet).slice(0, 3) as (string | number)[],
    };
  });

  return {
    id: `custom-${Date.now()}`,
    name: datasetName,
    description: `User-imported dataset with ${rows.length} observations and ${headers.length} variables.`,
    domain: 'Imported Quantitative Study',
    columns,
    data: rows,
    totalRows: rows.length,
  };
}
